                        failed += 1
                        logger.exception(
                            "failed to fetch data for '{}'".format(name)
                        )
                        continue
                    else:
                        cache.update(out.get_used_cache())

                try:
                    if not trust_remote:
                        return repo.cloud.pull(cache), failed
                    else:
                        return repo.cloud.trusted_pull(cache), failed
                except DownloadError as exc:
                    failed += exc.amount
    except CloneError:
