def _show_md(diff):
    from dvc.utils.diff import table

    rows = []
    for status in ["added", "deleted", "modified"]:
        entries = diff.get(status, [])
        if not entries:
            continue
        for entry in entries:
            path = entry["path"]
            checksum = entry.get("hash", "")
            if checksum:
                if isinstance(checksum, str):
                    checksum = checksum[0:8]
                elif isinstance(checksum, dict):
                    checksum = "{}..{}".format(checksum["old"][0:8], checksum["new"][0:8])
            rows.append([status, checksum, path])

    return table(["Status", "Hash", "Path"], rows, True)
