import logging
import os
from typing import Optional, List

from hdfs import InsecureClient

from dvc.tree.base import BaseTree

logger = logging.getLogger(__name__)

class WebHDFSTree(BaseTree):
    def __init__(self, repo, config):
        super().__init__(repo, config)
        self.hdfs_url = config.get("url")
        self.client = InsecureClient(self.hdfs_url)

    def exists(self, path: str) -> bool:
        try:
            self.client.status(path)
            return True
        except Exception as e:
            logger.debug(f"Failed to check existence of {path}: {e}")
            return False

    def _upload(self, from_path: str, to_path: str, **kwargs) -> Optional[int]:
        try:
            self.client.upload(from_path, to_path)
            return os.path.getsize(from_path)
        except Exception as e:
            logger.debug(f"Failed to upload {from_path} to {to_path}: {e}")
            return None

    def _download(self, from_path: str, to_path: str, **kwargs) -> Optional[int]:
        try:
            self.client.download(from_path, to_path)
            return os.path.getsize(to_path)
        except Exception as e:
            logger.debug(f"Failed to download {from_path} to {to_path}: {e}")
            return None

    def list(self, path: str, **kwargs) -> List[str]:
        try:
            return self.client.list(path)
        except Exception as e:
            logger.debug(f"Failed to list {path}: {e}")
            return []
