edit 54:90
def _ls(fs, path, recursive=None, dvc_only=False):
    if path and os.path.isdir(path):
        # If path is a local directory, list its contents directly
        return _list_local_dir(path, recursive, dvc_only)
    else:
        fs_path = fs.from_os_path(path)

        try:
            fs_path = fs.info(fs_path)["name"]
        except FileNotFoundError:
            return {}

        infos = {}
        for root, dirs, files in fs.walk(
            fs_path, dvcfiles=True, dvc_only=dvc_only
        ):
            entries = chain(files, dirs) if not recursive else files

            for entry in entries:
                entry_fs_path = fs.path.join(root, entry)
                relparts = fs.path.relparts(entry_fs_path, fs_path)
                name = os.path.join(*relparts)
                infos[name] = fs.info(entry_fs_path)

            if not recursive:
                break

        if not infos and fs.isfile(fs_path):
            infos[os.path.basename(path)] = fs.info(fs_path)

        ret = {}
        for name, info in infos.items():
            dvc_info = info.get("dvc_info", {})
            if dvc_info.get("outs") or not dvc_only:
                ret[name] = {
                    "isout": dvc_info.get("isout", False),
                    "isdir": info["type"] == "directory",
                    "isexec": info.get("isexec", False),
                }

        return ret

def _list_local_dir(path, recursive=None, dvc_only=False):
    """Lists the contents of a local directory."""
    ret = {}
    for root, dirs, files in os.walk(path):
        for entry in chain(files, dirs):
            entry_path = os.path.join(root, entry)
            relpath = os.path.relpath(entry_path, path)
            ret[relpath] = {
                "isout": False,
                "isdir": os.path.isdir(entry_path),
                "isexec": os.access(entry_path, os.X_OK),
            }
        if not recursive:
            break
    return ret
end_of_edit
