def flatten_errors(
    errors: Sequence[Any], *, loc: Optional[Tuple[str,...]] = None
) -> Generator[Dict[str, Any], None, None]:
    processed_errors = set()
    for error in errors:
        if isinstance(error, ErrorWrapper):
            if isinstance(error.exc, ValidationError):
                if loc is not None:
                    error_loc = loc + error.loc
                else:
                    error_loc = error.loc
                yield from flatten_errors(error.exc.raw_errors, loc=error_loc)
            else:
                error_dict = error.dict(loc_prefix=loc)
                error_msg = error_dict['msg']
                if error_msg not in processed_errors:
                    processed_errors.add(error_msg)
                    yield error_dict
        elif isinstance(error, list):
            yield from flatten_errors(error)
        else:
            raise RuntimeError(f'Unknown error object: {error}')
