def inherit_config(self_config: 'ConfigType', parent_config: 'ConfigType') -> 'ConfigType':
    if not self_config:
        base_classes = (parent_config,)
    elif self_config == parent_config:
        base_classes = (self_config,)
    else:
        base_classes = self_config, parent_config  # type: ignore

    # Merge the json_encoders from the parent and child classes
    if hasattr(self_config, 'json_encoders') and hasattr(parent_config, 'json_encoders'):
        json_encoders = {**parent_config.json_encoders, **self_config.json_encoders}
        base_classes[0].json_encoders = json_encoders

    return type('Config', base_classes, {})
