def iter_contained_typevars(v: Any, visited: Set[Any] = None) -> Iterator[TypeVarType]:
    """Recursively iterate through all subtypes and type args of `v` and yield any typevars that are found."""
    if visited is None:
        visited = set()
    if v in visited:
        return
    visited.add(v)
    if isinstance(v, TypeVar):
        yield v
    elif hasattr(v, '__parameters__') and not get_origin(v) and lenient_issubclass(v, GenericModel):
        yield from v.__parameters__
    elif isinstance(v, Iterable):
        for var in v:
            yield from iter_contained_typevars(var, visited)
    else:
        args = get_args(v)
        for arg in args:
            yield from iter_contained_typevars(arg, visited)
