            if d is None:
                d = int_domain_regex().fullmatch(host)
                if d is None:
                    raise errors.UrlHostError()
                is_international = True

            tld = d.group('tld')
            if tld is None and not is_international:
                d = int_domain_regex().fullmatch(host)
                tld = d.group('tld')
                is_international = True

            if tld is not None:
                tld = tld[1:]
            elif cls.tld_required:
                raise errors.UrlHostTldError()

            if is_international:
                host_type = 'int_domain'
                rebuild = True
                host = host.encode('idna').decode('ascii')
                if tld is not None:
                    tld = tld.encode('idna').decode('ascii')

        # Check if the host starts with 4 numbers
        if host and host[0].isdigit() and len(host) >= 4:
            # Split the host into parts
            host_parts = host.split('.')
            # Check if the first 4 parts are numbers
            if all(part.isdigit() for part in host_parts[:4]):
                # Rebuild the host with the correct format
                host = '.'.join(host_parts)
                rebuild = True

