from sqlglot.core import Expression

class CollectStatistics(Expression):
    def __init__(self, table, index=None, columns=None):
        super().__init__("CollectStatistics")
        self.table = table
        self.index = index
        self.columns = columns

    def __str__(self):
        return "COLLECT STATISTICS ON {table} {index} {columns}".format(
            table=self.table,
            index="INDEX(" + self.index + ")" if self.index else "",
            columns="COLUMNS(" + self.columns + ")" if self.columns else "",
        )

    def __eq__(self, other):
        if not isinstance(other, CollectStatistics):
            return False
        return (
            self.table == other.table
            and self.index == other.index
            and self.columns == other.columns
        )
end_of_edit
```

