                        text += escaped_sequence
                        continue

                current = self._current - 1
                self._advance(alnum=True)
                # Include '#' as part of the identifier for T-SQL dialect
                if self.dialect == "tsql" and self._peek == "#":
                    text += self._peek
                else:
